-- Code generated by factory from specs/sales/list-top-discount-stores/spec.yaml. DO NOT EDIT.

-- name: ListTopDiscountStores :many
SELECT t2.store_code, t2.discount, t2.amount
FROM (
    SELECT t1.store_code AS store_code, t1.discount AS discount, t1.amount AS amount
    FROM daily_sales AS t1
    WHERE (t1.sales_date = sqlc.arg(sales_date)::date)
      AND (t1.discount > '0'::numeric)
) AS t2
ORDER BY t2.discount DESC, t2.store_code
LIMIT 2;
